-- ============================================================
-- ALTER: fims.budget_allocation — add request_referrence_no, generated by the database
-- A request reference number for every allocation, formatted RR-001, RR-002, ... RR-999, RR-1000, ...
-- (zero-padded to 3 digits; it simply grows past 999, it is never cut off). It is generated BY THE DATABASE:
-- the column's DEFAULT calls fims.next_request_referrence_no(), which takes the next value of a sequence, so
--   * every INSERT that does not name the column gets the next number, whoever inserts (the API, a script, psql);
--   * two inserts at the same moment can never get the same number (a sequence is atomic);
--   * numbers are never reused: a soft-deleted row keeps its number, and a rolled-back or failed INSERT leaves
--     a gap in the series (that is how sequences work; the numbers stay unique and increasing).
-- BudgetAllocationService does not write the column — it ignores it in the request body, so the generated value
-- always stands — and returns it from the list / read routes (and from add, for the row just created).
--
-- Rows that already exist are numbered once, in the order they were created (created_at, then allocation_id),
-- so the oldest allocation is RR-001; new rows continue after them. Rows whose column is already filled are kept
-- as they are, and the counter is moved past the highest RR-number found, so nothing is ever duplicated.
-- A UNIQUE index guarantees that: there is at most one row per reference.
--
-- NOTE the spelling "referrence": that is the column's name, exactly as it was asked for.
-- Idempotent: safe to run any number of times.
-- ============================================================
ALTER TABLE fims.budget_allocation
    ADD COLUMN IF NOT EXISTS request_referrence_no VARCHAR(50);

COMMENT ON COLUMN fims.budget_allocation.request_referrence_no IS
    'Request reference number, generated by the database (RR-001, RR-002, ...): the column default takes the next value of fims.budget_allocation_request_referrence_no_seq. Never reused; unique.';

-- ── the counter ────────────────────────────────────────────────────────────────────────────────────────────────
CREATE SEQUENCE IF NOT EXISTS fims.budget_allocation_request_referrence_no_seq;
-- owned by the column: dropping the column drops the counter with it
ALTER SEQUENCE fims.budget_allocation_request_referrence_no_seq OWNED BY fims.budget_allocation.request_referrence_no;

-- ── the generator: 'RR-' + the next number, padded to at least 3 digits (it never truncates: 1000 -> RR-1000) ──
CREATE OR REPLACE FUNCTION fims.next_request_referrence_no() RETURNS VARCHAR(50)
LANGUAGE sql
AS $$
    SELECT 'RR-' || lpad(n::text, GREATEST(3, length(n::text)), '0')
    FROM (SELECT nextval('fims.budget_allocation_request_referrence_no_seq') AS n) AS s
$$;

COMMENT ON FUNCTION fims.next_request_referrence_no() IS
    'Next request reference number (RR-001, RR-002, ...): takes the next value of fims.budget_allocation_request_referrence_no_seq. Used as the default of fims.budget_allocation.request_referrence_no.';

-- ── never hand out a number that is already in the table: move the counter past the highest RR-number present ──
DO $$
DECLARE
    highest BIGINT;
    last_given BIGINT;   -- the last number the counter has handed out (0 = none yet)
    seq_value BIGINT;
    was_called BOOLEAN;
BEGIN
    SELECT COALESCE(MAX(substring(request_referrence_no FROM '^RR-([0-9]+)$')::BIGINT), 0)
      INTO highest
      FROM fims.budget_allocation;

    SELECT last_value, is_called
      INTO seq_value, was_called
      FROM fims.budget_allocation_request_referrence_no_seq;

    IF was_called THEN
        last_given := seq_value;
    ELSE
        last_given := 0;
    END IF;

    IF highest > last_given THEN
        PERFORM setval('fims.budget_allocation_request_referrence_no_seq', highest, true);
    END IF;
END $$;

-- ── number the rows that have none yet, oldest first (this also covers soft-deleted rows) ──────────────────────
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT allocation_id
          FROM fims.budget_allocation
         WHERE request_referrence_no IS NULL
         ORDER BY created_at NULLS FIRST, allocation_id
    LOOP
        UPDATE fims.budget_allocation
           SET request_referrence_no = fims.next_request_referrence_no()
         WHERE allocation_id = r.allocation_id;
    END LOOP;
END $$;

-- ── from now on the database fills it in ───────────────────────────────────────────────────────────────────────
ALTER TABLE fims.budget_allocation
    ALTER COLUMN request_referrence_no SET DEFAULT fims.next_request_referrence_no();

-- one row per reference (NULLs, if anyone inserts one explicitly, do not collide)
CREATE UNIQUE INDEX IF NOT EXISTS uq_budget_allocation_request_referrence_no
    ON fims.budget_allocation (request_referrence_no);
